const now = Date.now();
const required = ['hvac/roof/temp_out','hvac/house/temp_return','hvac/mass/temp_out','hvac/core/temp'];
let values = context.get('values') || {};
if (required.includes(msg.topic) && !msg.retain) {
  const numeric = (typeof msg.payload === 'string' && msg.payload.trim() !== '') || typeof msg.payload === 'number';
  const value = numeric ? Number(msg.payload) : NaN;
  if (Number.isFinite(value) && value >= -50 && value <= 100) values[msg.topic] = {value, time: now};
  else delete values[msg.topic];
  context.set('values', values);
}
const fresh = required.every(k => values[k] && now - values[k].time >= 0 && now - values[k].time < 120000);
let mode = 'FAILSAFE';
if (fresh) {
  const roof = values['hvac/roof/temp_out'].value;
  const house = values['hvac/house/temp_return'].value;
  const mass = values['hvac/mass/temp_out'].value;
  const core = values['hvac/core/temp'].value;
  const requested = flow.get('requested') || 'IDLE';
  if (requested === 'DIAGNOSTICS') mode = 'DIAGNOSTICS';
  else if (requested !== 'AUTO') mode = 'IDLE';
  else if (roof - core >= 5) mode = 'CHARGE_THERMAL_MASS';
  else if (mass - house >= 3) mode = 'HEAT_HOUSE';
  else if (house - roof >= 4) mode = 'NIGHT_COOLING';
  else mode = 'IDLE';
}
node.status({fill: mode === 'FAILSAFE' ? 'red' : 'blue', shape:'dot', text:mode + ' (advisory)'});
return {topic:'hvac/controller/mode', payload:mode, qos:'0', retain:false};

const fields = {'hvac/outdoor/temp':'outdoor','hvac/roof/temp_in':'roof_in','hvac/roof/temp_out':'roof_out','hvac/house/temp_return':'house_return','hvac/house/temp_supply':'house_supply','hvac/mass/temp_in':'mass_in','hvac/mass/temp_out':'mass_out','hvac/core/temp':'core','hvac/blower/power':'blower_power','hvac/blower/current':'blower_current'};
const field = fields[msg.topic];
const numeric = (typeof msg.payload === 'string' && msg.payload.trim() !== '') || typeof msg.payload === 'number';
if (!field || msg.retain || !numeric) return null;
const value = Number(msg.payload);
if (!Number.isFinite(value)) return null;
const org = env.get('INFLUX_ORG');
const bucket = env.get('INFLUX_BUCKET');
const token = env.get('INFLUX_TOKEN');
const base = env.get('INFLUX_URL');
if (!org || !bucket || !token || !base) { node.error('InfluxDB configuration missing'); return null; }
msg.url = base.replace(/\/$/, '') + '/api/v2/write?org=' + encodeURIComponent(org) + '&bucket=' + encodeURIComponent(bucket) + '&precision=ms';
msg.method = 'POST';
msg.headers = {Authorization:'Token ' + token, 'Content-Type':'text/plain; charset=utf-8'};
msg.payload = 'hvac ' + field + '=' + value + ' ' + Date.now();
return msg;
